using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using ParkingLotEnvironment.Training;
namespace ParkingLotEnvironment.CloudPilot {
public static class ContextBuilder {
 public const string W="Assets/ParkingLotEnvironment/CloudPilot/ParkingContext20261105";
 static Transform holder;static GameObject root;static Material roof;static readonly List<string> notes=new List<string>();
 public static Bounds BoundsOf(GameObject g){var rr=g.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();if(rr.Length==0)throw new Exception("No visible geometry "+g.name);var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
 static Material Mat(string n,Color c,float smooth){var m=new Material(Shader.Find("Standard")){name=n,color=c};m.SetFloat("_Glossiness",smooth);AssetDatabase.CreateAsset(m,W+"/"+n+".mat");return m;}
 static GameObject Box(string name,Vector3 p,Vector3 size,Material m,bool collider=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(holder,false);g.transform.position=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;if(!collider)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());GameObjectUtility.SetStaticEditorFlags(g,StaticEditorFlags.ReflectionProbeStatic|StaticEditorFlags.ContributeGI);g.GetComponent<MeshRenderer>().scaleInLightmap=.2f;return g;}
 static GameObject Building(string sourceName,string id,Vector3 position,Vector3 size,float yaw,bool near){var source=root.transform.Find("AG_Photorealistic3D_Assets/"+sourceName);if(!source)throw new Exception("Approved building missing "+sourceName);var g=UnityEngine.Object.Instantiate(source.gameObject,holder);g.name=id;g.transform.SetPositionAndRotation(Vector3.zero,Quaternion.Euler(0,yaw,0));g.transform.localScale=Vector3.one;g.SetActive(true);var b=BoundsOf(g);g.transform.localScale=new Vector3(size.x/b.size.x,size.y/b.size.y,size.z/b.size.z);if(Mathf.Abs(yaw%180)>.1f)g.transform.localScale=new Vector3(size.z/b.size.z,size.y/b.size.y,size.x/b.size.x);b=BoundsOf(g);g.transform.position+=new Vector3(position.x-b.center.x,-b.min.y,position.z-b.center.z);b=BoundsOf(g);
  foreach(var r in g.GetComponentsInChildren<MeshRenderer>()){r.receiveShadows=true;r.shadowCastingMode=ShadowCastingMode.On;GameObjectUtility.SetStaticEditorFlags(r.gameObject,StaticEditorFlags.ContributeGI|StaticEditorFlags.ReflectionProbeStatic);r.receiveGI=near?ReceiveGI.Lightmaps:ReceiveGI.LightProbes;r.scaleInLightmap=near?.35f:0;}
  // Closed roof and four parapets make the same approved facade kit valid above eye level.
  Box(id+"_ClosedRoof",new Vector3(b.center.x,b.max.y-.08f,b.center.z),new Vector3(b.size.x-.18f,.12f,b.size.z-.18f),roof);
  for(int k=0;k<4;k++)Box(id+"_Parapet",new Vector3(b.center.x+(k<2?(k==0?-1:1)*(b.extents.x-.10f):0),b.max.y+.15f,b.center.z+(k>=2?(k==2?-1:1)*(b.extents.z-.10f):0)),k<2?new Vector3(.16f,.3f,b.size.z):new Vector3(b.size.x,.3f,.16f),roof);
  notes.Add(id+" "+b);return g;
 }
 static void Ground(string name,float minX,float maxX,float minZ,float maxZ,float y,Material m,bool collider){var points=new[]{new Vector3(minX,y,minZ),new Vector3(minX,y,maxZ),new Vector3(maxX,y,maxZ),new Vector3(maxX,y,minZ)};var mesh=new Mesh{name=name,vertices=points,uv=points.Select(p=>new Vector2(p.x/30,p.z/30)).ToArray(),triangles=new[]{0,1,2,0,2,3}};mesh.RecalculateNormals();mesh.RecalculateTangents();Unwrapping.GenerateSecondaryUVSet(mesh);AssetDatabase.CreateAsset(mesh,W+"/"+name+".asset");var g=new GameObject(name);g.transform.SetParent(holder,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=m;GameObjectUtility.SetStaticEditorFlags(g,StaticEditorFlags.ReflectionProbeStatic|StaticEditorFlags.ContributeGI);r.scaleInLightmap=.05f;if(collider)g.AddComponent<MeshCollider>().sharedMesh=mesh;}
 public static void Apply(GameObject sceneRoot,string output){root=sceneRoot;holder=new GameObject("ParkingContext_ApprovedKitExtension").transform;holder.SetParent(root.transform,false);roof=Mat("ApprovedRoofConcrete",new Color(.48f,.47f,.44f),.13f);
  var layout=root.GetComponentInChildren<ParkingTrainingLayout>();var old=layout.transform.Find("Parked_T_4");if(!old)throw new Exception("Cargo slot missing");old.gameObject.SetActive(false);var wrap=new GameObject("Parked_T_4_PortedModel");wrap.transform.SetParent(layout.transform,false);var porter=PorterImport.Create(wrap.transform);porter.transform.localRotation=Quaternion.Euler(0,90,0);var bounds=BoundsOf(wrap);porter.transform.position+=new Vector3(-5.6f-bounds.center.x,.005f-bounds.min.y,-4.5f-bounds.center.z);bounds=BoundsOf(wrap);var col=wrap.AddComponent<BoxCollider>();col.center=bounds.center;col.size=bounds.size;var obstacle=layout.obstacles.Single(o=>o.id=="Parked_T_4");obstacle.id=wrap.name;obstacle.model="Porter II by max7th / CC BY 4.0";obstacle.category="Hyundai Porter II blue 1-ton cargo";obstacle.center=bounds.center;obstacle.size=bounds.size;layout.truckModelNote="Blue Hyundai Porter II: max7th, Thingiverse 4685394, CC BY 4.0; separately assembled print components with new materials. Delivery box truck is the existing generic model.";EditorUtility.SetDirty(layout);
  // Fill missing foreground sides with the approved four-sided buildings, preserving all approved materials and lighting.
  const string brick="AG_3D_ContextBuilding_4_27",villa="AG_3D_ContextBuilding_15_24",shop="AG_3D_ContextBuilding_-6_24",apt="AG_3D_ContextBuilding_14_48";
  Building(brick,"LeftFrontBrick",new Vector3(-13.7f,0,-16.5f),new Vector3(8.1f,11.6f,9.5f),-90,true);
  Building(villa,"LeftEntranceVilla",new Vector3(-13.7f,0,-26),new Vector3(8.1f,9.7f,9.1f),-90,true);
  Building(shop,"RightFrontShop",new Vector3(14.1f,0,-7.4f),new Vector3(8.4f,10.8f,9.3f),90,true);
  Building(brick,"RightMiddleBrick",new Vector3(14.1f,0,-16.8f),new Vector3(8.4f,13.0f,9.2f),90,true);
  Building(villa,"RightEntranceVilla",new Vector3(14.1f,0,-26.1f),new Vector3(8.4f,10.3f,9.2f),90,true);
  // Opposite frontage and a second block close the view when the chase camera turns back toward the entrance.
  for(int i=0;i<7;i++)Building(i%3==0?brick:i%3==1?villa:shop,"OppositeStreet_"+i,new Vector3(-29+i*10.5f,0,-45.7f),new Vector3(9.8f,9.6f+(i%3)*3.0f,10.4f),180,false);
  Building(apt,"BackgroundApartmentLeft",new Vector3(-28,0,-62),new Vector3(13,26,12),0,false);Building(apt,"BackgroundApartmentRight",new Vector3(23,0,-64),new Vector3(14,30,12),0,false);
  for(int side=-1;side<=1;side+=2)for(int i=0;i<3;i++)Building(i%2==0?brick:shop,"OuterBlock_"+side+"_"+i,new Vector3(side*32,0,-23+i*24),new Vector3(11,12+(i%2)*6,17),side<0?-90:90,false);
  for(int i=0;i<4;i++)Building(i%2==0?shop:villa,"RearInfill_"+i,new Vector3(-24+i*13,0,39),new Vector3(11.5f,12+(i%2)*5,10),0,false);
  var asphalt=root.transform.Find("Zone_Asphalt/default").GetComponent<Renderer>().sharedMaterial;
  Ground("ExtendedCityGround",-180,180,-180,180,-.16f,root.transform.Find("DaylightPass_Context/Daylight_FinalGround").GetComponent<Renderer>().sharedMaterial,false);
  Ground("EntranceStreetConnection",-2.8f,4.2f,-31.2f,-26,-.006f,asphalt,true);Ground("EntrancePublicStreet",-75,75,-38.5f,-31.2f,-.012f,asphalt,true);
  var paving=Mat("StreetPaving",new Color(.39f,.39f,.37f),.13f);Box("OppositeStreetSidewalk",new Vector3(0,.025f,-39.8f),new Vector3(90,.09f,2.4f),paving);Box("EntranceLeftSidewalk",new Vector3(-22,.015f,-30.25f),new Vector3(38,.08f,1.6f),paving);Box("EntranceRightSidewalk",new Vector3(24,.015f,-30.25f),new Vector3(39,.08f,1.6f),paving);
  // Scene-only MSAA state is restored when the scene is disabled. ProjectSettings remain untouched.
  var camera=root.GetComponentInChildren<Camera>();camera.allowHDR=true;camera.allowMSAA=true;
  foreach(var r in root.GetComponentsInChildren<Renderer>())if(r.transform.IsChildOf(layout.transform)&&!r.name.Contains("Glass"))foreach(var m in r.sharedMaterials)if(m&&m.name.StartsWith("Parked_T_")&&m.HasProperty("_Glossiness")){/* Approved material assets are referenced as-is. */}
  Physics.SyncTransforms();File.WriteAllText(output+"/layout.json",JsonUtility.ToJson(layout,true));File.WriteAllLines(output+"/context-changes.txt",notes);File.AppendAllText(output+"/context-changes.txt","Approved asphalt, building materials, camera tonemapper, sun and original exposure retained. Added intact Porter cabin and 24 closed-volume context buildings.\n");VehicleAppearance.Apply(root,output);
 }
 public static void Validate(GameObject sceneRoot,string output){RefinementBuilder.Validate(sceneRoot,output);var holder=sceneRoot.transform.Find("ParkingContext_ApprovedKitExtension");foreach(var r in holder.GetComponentsInChildren<Renderer>()){var b=r.bounds;if(b.size.y>4&&b.min.x<8.7f&&b.max.x> -8.7f&&b.min.z<14&&b.max.z> -20)throw new Exception("New building intrudes into parking lot: "+r.name);}
  var cargo=sceneRoot.GetComponentInChildren<ParkingTrainingLayout>().transform.Find("Parked_T_4_PortedModel");if(!cargo||!cargo.gameObject.activeInHierarchy)throw new Exception("Porter missing");var b2=BoundsOf(cargo.gameObject);if(b2.size.x<4.9f||b2.size.x>5.5f||b2.size.y<1.9f||b2.size.y>2.4f||b2.size.z>2.3f)throw new Exception("Porter assembly dimensions invalid "+b2);
  File.AppendAllText(output+"/map-validation.txt","Porter assembled bounds="+b2+"; approved original meshes/materials untouched; new buildings outside parking footprint.\n");
 }
}}
